using Microsoft.CodeAnalysis;
using Microsoft.CodeAnalysis.CSharp;
using Microsoft.CodeAnalysis.CSharp.Syntax;
using Microsoft.CodeAnalysis.Testing;

namespace Receipts.GeneratedTests;

public class ExcludeFromCodeCoverageRequirementTests
{
    private const string Source = """
        using MessagePack;

        namespace TestNs
        {
            [MessagePackObject]
            public class MyObject
            {
                [Key(0)]
                public int Value { get; set; }
            }

            [MessagePackObject]
            public class MyStringKeyObject
            {
                [Key("v")]
                public int Value { get; set; }
            }

            [Union(0, typeof(UnionImpl))]
            public interface IMyUnion
            {
            }

            [MessagePackObject]
            public class UnionImpl : IMyUnion
            {
                [Key(0)]
                public int X { get; set; }
            }

            [GeneratedMessagePackResolver]
            partial class MyResolver
            {
            }
        }
        """;

    [Fact]
    public async Task AllGeneratedTypesAreExcludedFromCodeCoverage()
    {
        (List<string> checkedNames, List<string> missing) = await CheckAsync();
        Assert.Contains(checkedNames, n => n.EndsWith("Formatter", StringComparison.Ordinal));
        Assert.Contains(checkedNames, n => n.EndsWith("MyResolver", StringComparison.Ordinal));
        Assert.True(missing.Count == 0, "Generated types without ExcludeFromCodeCoverage: " + string.Join(", ", missing));
    }

    [Fact]
    public async Task GeneratedCodeContainsAttributeWithoutAnySetting()
    {
        CSharpParseOptions parseOptions = new CSharpParseOptions(LanguageVersion.Latest);
        ImmutableArray<MetadataReference> frameworkRefs = await ReferenceAssemblies.Net.Net80.ResolveAsync(LanguageNames.CSharp, CancellationToken.None);
        CSharpCompilation compilation = CSharpCompilation.Create(
            "TestAssembly",
            new[] { CSharpSyntaxTree.ParseText(Source, parseOptions) },
            frameworkRefs.Concat(ReferencesHelper.GetReferences(ReferencesSet.MessagePack)),
            new CSharpCompilationOptions(OutputKind.DynamicallyLinkedLibrary));
        GeneratorDriver driver = CSharpGeneratorDriver.Create(new[] { new global::MessagePack.SourceGenerator.MessagePackGenerator().AsSourceGenerator() }, parseOptions: parseOptions);
        driver = driver.RunGenerators(compilation);
        GeneratorDriverRunResult result = driver.GetRunResult();
        Assert.NotEmpty(result.GeneratedTrees);
        Assert.Contains(result.GeneratedTrees, t => t.ToString().Contains("ExcludeFromCodeCoverage"));
    }

    private static async Task<(List<string> CheckedNames, List<string> Missing)> CheckAsync()
    {
        CSharpParseOptions parseOptions = new CSharpParseOptions(LanguageVersion.Latest);
        ImmutableArray<MetadataReference> frameworkRefs = await ReferenceAssemblies.Net.Net80.ResolveAsync(LanguageNames.CSharp, CancellationToken.None);
        CSharpCompilation compilation = CSharpCompilation.Create(
            "TestAssembly",
            new[] { CSharpSyntaxTree.ParseText(Source, parseOptions) },
            frameworkRefs.Concat(ReferencesHelper.GetReferences(ReferencesSet.MessagePack)),
            new CSharpCompilationOptions(OutputKind.DynamicallyLinkedLibrary));
        GeneratorDriver driver = CSharpGeneratorDriver.Create(new[] { new global::MessagePack.SourceGenerator.MessagePackGenerator().AsSourceGenerator() }, parseOptions: parseOptions);
        driver.RunGeneratorsAndUpdateCompilation(compilation, out Compilation output, out ImmutableArray<Diagnostic> generatorDiagnostics);
        Assert.Empty(generatorDiagnostics.Where(d => d.Severity == DiagnosticSeverity.Error));
        Assert.Empty(output.GetDiagnostics().Where(d => d.Severity == DiagnosticSeverity.Error));

        var checkedNames = new List<string>();
        var missing = new List<string>();
        foreach (SyntaxTree tree in output.SyntaxTrees.Where(t => !compilation.SyntaxTrees.Contains(t)))
        {
            SemanticModel model = output.GetSemanticModel(tree);
            foreach (ClassDeclarationSyntax cls in tree.GetRoot().DescendantNodes().OfType<ClassDeclarationSyntax>())
            {
                bool isPartial = cls.Modifiers.Any(m => m.IsKind(SyntaxKind.PartialKeyword));
                bool isResolver = cls.Identifier.ValueText == "MyResolver";
                if (isPartial && !isResolver)
                {
                    continue;
                }

                if (cls.Parent is ClassDeclarationSyntax parent && !parent.Modifiers.Any(m => m.IsKind(SyntaxKind.PartialKeyword)) && parent.Identifier.ValueText != "MyResolver")
                {
                    continue;
                }

                INamedTypeSymbol? symbol = model.GetDeclaredSymbol(cls);
                Assert.NotNull(symbol);
                string name = symbol!.ToDisplayString();
                checkedNames.Add(name);
                if (!symbol.GetAttributes().Any(a => a.AttributeClass?.ToDisplayString() == "System.Diagnostics.CodeAnalysis.ExcludeFromCodeCoverageAttribute"))
                {
                    missing.Add(name);
                }
            }
        }

        return (checkedNames, missing);
    }
}

